Correct Answer:
function attachValidation(input) {
  const validate = () => {
    input.setCustomValidity(input.value === "admin"
      ? "Choose a different username." : "");
  };
  input.addEventListener("input", validate);
  validate();
  return () => input.removeEventListener("input", validate);
}

